DROP TABLE IF EXISTS `Commande`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Commande` (
  `id_commande` int NOT NULL AUTO_INCREMENT,
  `date_creation` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `statut` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'En attente',
  `total_marchandises` double NOT NULL,
  `frais_livraison` double NOT NULL,
  `commission` double NOT NULL DEFAULT '0',
  `code_verification` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_user_client` int NOT NULL,
  `mode_paiement` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ESPECES',
  `mode_paiement_status` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `validee_par_vendeur` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id_commande`),
  KEY `Commande_id_user_client_fkey` (`id_user_client`),
  CONSTRAINT `Commande_id_user_client_fkey` FOREIGN KEY (`id_user_client`) REFERENCES `Client` (`id_user`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=637 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
