--
-- Table structure for table `Feedback`
--

DROP TABLE IF EXISTS `Feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Feedback` (
  `id_feedback` int NOT NULL AUTO_INCREMENT,
  `note` int NOT NULL,
  `commentaire` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_publication` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `type_feedback` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_user_client` int NOT NULL,
  `id_livraison` int DEFAULT NULL,
  `id_user_vendeur` int DEFAULT NULL,
  PRIMARY KEY (`id_feedback`),
  KEY `Feedback_id_user_client_fkey` (`id_user_client`),
  KEY `Feedback_id_livraison_fkey` (`id_livraison`),
  KEY `Feedback_id_user_vendeur_fkey` (`id_user_vendeur`),
  CONSTRAINT `Feedback_id_livraison_fkey` FOREIGN KEY (`id_livraison`) REFERENCES `Livraison` (`id_livraison`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Feedback_id_user_client_fkey` FOREIGN KEY (`id_user_client`) REFERENCES `Client` (`id_user`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `Feedback_id_user_vendeur_fkey` FOREIGN KEY (`id_user_vendeur`) REFERENCES `Vendeur` (`id_user`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=277 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

